      "arFull": "یٰنِسَآءَ النَّبِیِّ مَنْ یَّاْتِ مِنْكُنَّ بِفَاحِشَةٍ مُّبَیِّنَةٍ یُّضٰعَفْ لَهَا الْعَذَابُ ضِعْفَیْنِ ؕ وَكَانَ ذٰلِكَ عَلَی اللّٰهِ یَسِیْرًا ۟",
