      "arFull": "اِنْ تُبْدُوْا شَیْـًٔا اَوْ تُخْفُوْهُ فَاِنَّ اللّٰهَ كَانَ بِكُلِّ شَیْءٍ عَلِیْمًا ۟",
      "ur": "تم کسی چیز کو ﻇاہر کرو یا مخفی رکھو اللہ تو ہر چیز کا بخوبی علم رکھنے واﻻ ہے.",
