      "arFull": "یُّصْلِحْ لَكُمْ اَعْمَالَكُمْ وَیَغْفِرْ لَكُمْ ذُنُوْبَكُمْ ؕ وَمَنْ یُّطِعِ اللّٰهَ وَرَسُوْلَهٗ فَقَدْ فَازَ فَوْزًا عَظِیْمًا ۟",
