      "arFull": "لِّیُعَذِّبَ اللّٰهُ الْمُنٰفِقِیْنَ وَالْمُنٰفِقٰتِ وَالْمُشْرِكِیْنَ وَالْمُشْرِكٰتِ وَیَتُوْبَ اللّٰهُ عَلَی الْمُؤْمِنِیْنَ وَالْمُؤْمِنٰتِ ؕ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِیْمًا ۟۠",
